"""Build protocol examples from the locally captured experiment evidence."""
import sys,json,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'src'))
from trace_hunter.adapters import normalize,span,ref
from trace_hunter.protocol import validate
from trace_hunter.identity import upgrade_header
